      "file": "src/features/places/PlaceNoteActions.tsx",
      "content": "/** @jsx jsx */\nimport { React,jsx } from 'jimu-core';\nimport { useWidgetLocale } from '../../i18n/WidgetLocale';\nimport { DetectionCrop } from '../detections/LinkedDetectionPreview';\nimport type { DetectionPreviewLoader } from '../detections/detectionPreview';\nimport type { Place } from './placesModel';\nimport type { PlaceNoteDestination,PlaceNoteOptions,PlaceNoteImageContext } from './placeNote';\nexport function PlaceNoteActions({place,enterpriseEnabled,onNote,currentImageId,onGetImage,onLoadPreview,phase='idle',onCancel}:{place:Place;enterpriseEnabled:boolean;onNote:(destination:PlaceNoteDestination,options?:PlaceNoteOptions)=>void;currentImageId?:string|null;onGetImage?:()=>Promise<PlaceNoteImageContext|null>;onLoadPreview?:DetectionPreviewLoader;phase?:'idle'|'capturing'|'picking';onCancel?:()=>void}){\n const {owned:text,formatLocale}=useWidgetLocale(),[open,setOpen]=React.useState(false),[destination,setDestination]=React.useState<PlaceNoteDestination>('local'),[pick,setPick]=React.useState(false),[include,setInclude]=React.useState(false),[image,setImage]=React.useState<PlaceNoteImageContext|null>(null),[x,setX]=React.useState(.5),[y,setY]=React.useState(.5),[size,setSize]=React.useState(.3);\n const latest=React.useRef({phase,onCancel});latest.current={phase,onCancel};React.useEffect(()=>()=>{if(latest.current.phase!=='idle')latest.current.onCancel?.();},[]);\n React.useEffect(()=>{if(phase==='idle')return;const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();onCancel?.();}};window.addEventListener('keydown',key,true);return()=>window.removeEventListener('keydown',key,true);},[phase,onCancel]);\n React.useEffect(()=>{let active=true;setInclude(false);setImage(null);if(open&&onGetImage)void onGetImage().then(value=>{if(active&&value){setImage(value);setX(value.center[0]);setY(value.center[1]);}},()=>{});return()=>{active=false;};},[open,currentImageId,onGetImage]);\n const control:React.CSSProperties={width:'100%',minHeight:28,minWidth:0,padding:'4px 6px',border:'1px solid #61846e',borderRadius:5,background:'#284b38',color:'#e3eddf',fontSize:11,cursor:'pointer',boxSizing:'border-box'};\n const bounds={x:Math.max(0,Math.min(1-size,x-size/2)),y:Math.max(0,Math.min(1-size,y-size/2)),width:size,height:size};\n const date=image?.capturedAt&&Number.isFinite(new Date(image.capturedAt).getTime())?new Intl.DateTimeFormat(formatLocale,{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(image.capturedAt)):text('Capture date unknown');\n return <div style={{display:'grid',gap:5,marginTop:5,minWidth:0}}>{!open?<button type=\"button\" style={control} onClick={()=>setOpen(true)}>{text('Add field note')}</button>:phase!=='idle'?<React.Fragment><span role=\"status\" style={{fontSize:10}}>{text(phase==='capturing'?'Preparing image\u2026':'Click the map to adjust the note location. Escape cancels.')}</span><button type=\"button\" style={control} onClick={onCancel}>{text('Cancel note preparation')}</button></React.Fragment>:<React.Fragment>\n <label style={{display:'grid',gap:3,fontSize:10,margin:0}}>{text('Save to')}<select aria-label={text('Place note destination')} value={destination} style={control} onChange={e=>setDestination(e.target.value as PlaceNoteDestination)}><option value=\"local\">{text('Local')}</option><option value=\"enterprise\" disabled={!enterpriseEnabled}>{text('Enterprise')}</option><option value=\"workspace\">{text('Workspace')}</option></select></label>\n <div style={{fontSize:9,overflowWrap:'anywhere'}}>{text('Mapped place location')}: {place.lat.toFixed(6)}, {place.lon.toFixed(6)}</div>\n <label style={{display:'flex',gap:5,fontSize:10,margin:0,alignItems:'start'}}><input type=\"checkbox\" checked={pick} onChange={e=>setPick(e.target.checked)} style={{margin:'2px 0 0'}}/><span>{text('Adjust location on map')}</span></label>\n <label style={{display:'flex',gap:5,fontSize:10,margin:0,alignItems:'start'}}><input type=\"checkbox\" checked={include} disabled={!image} onChange={e=>setInclude(e.target.checked)} style={{margin:'2px 0 0'}}/><span>{text('Attach cropped current image')}</span></label>\n {include&&image&&<React.Fragment><small style={{fontSize:9,overflowWrap:'anywhere'}}>{text('Mapillary image')}: {image.imageId} \u00b7 {date} (UTC)</small><DetectionCrop preview={{imageId:image.imageId,bounds}} load={onLoadPreview} alt=\"Place image crop preview\"/><details style={{fontSize:10}}><summary style={{cursor:'pointer'}}>{text('Adjust crop')}</summary>{[[text('Horizontal center'),x,setX],[text('Vertical center'),y,setY],[text('Crop size'),size,setSize]].map(([label,value,change])=><label key={String(label)} style={{display:'grid',gap:2,marginTop:4}}>{String(label)}<input aria-label={String(label)} type=\"range\" min={label===text('Crop size')?0.1:0} max={label===text('Crop size')?0.8:1} step=\"0.01\" value={value as number} onChange={event=>(change as (value:number)=>void)(Number(event.target.value))} style={{width:'100%',minWidth:0}}/></label>)}</details><small style={{fontSize:9}}>{text('Attach only if this crop shows the place. Visibility is not confirmed.')}</small></React.Fragment>}\n {!image&&<small style={{fontSize:9}}>{text('Open an image to attach a crop.')}</small>}\n <button type=\"button\" style={control} onClick={()=>onNote(destination,{pickLocation:pick,...(include&&image?{image:{imageId:image.imageId,bounds,capturedAt:image.capturedAt}}:{})})}>{text(pick?'Choose location and create draft':'Create draft here')}</button>\n </React.Fragment>}</div>;\n}\n"
