      "file": "tests/placeNoteReview.test.cjs",
      "content": "const fs=require('node:fs'),path=require('node:path'),test=require('node:test'),assert=require('node:assert/strict'),ts=require(process.env.MAPILLARY_TYPESCRIPT||'typescript');\nconst root=path.resolve(__dirname,'../src');function load(file){const p=path.resolve(root,file),m={exports:{}};new Function('require','module','exports',ts.transpileModule(fs.readFileSync(p,'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.CommonJS}}).outputText)(id=>load(path.relative(root,path.resolve(path.dirname(p),id+'.ts'))),m,m.exports);return m.exports;}\nconst {PlaceNoteReview}=load('features/places/PlaceNoteReview.ts'),api=load('features/detections/detectionImageAttachment.ts'),id='11111111-1111-4111-8111-111111111111';\nfunction fixture(){const state={place:{id:'place-A',name:'Library',category:'library',lon:29,lat:41,address:'Main St',website:'https://example.com',release:'2026-10'},view:{destroyed:false},imageId:'123',enabled:true},opened=[],removed=[],phases=[],errors=[];let pick;const f={state,opened,removed,phases,errors,captures:0,blocked:false};f.owner=new PlaceNoteReview({context:()=>({...state}),blocked:()=>f.blocked,capture:async()=>{f.captures++;return id},remove:async value=>removed.push(value),draw(){},clear(){},open:(seed,destination)=>opened.push({seed,destination}),phase:value=>phases.push(value),error:value=>errors.push(value),pick:(picked,cancelled)=>{pick={picked,cancelled};return()=>{const p=pick;pick=null;p?.cancelled();}}});f.pick=point=>pick.picked(point);f.setCapture=work=>f.owner.host.capture=work;return f;}\nconst image={imageId:'123',bounds:{x:.2,y:.3,width:.3,height:.3},capturedAt:1735689600000};\ntest('all destinations use the reviewed mapped position without attaching or saving automatically',async()=>{for(const destination of['local','enterprise','workspace']){const f=fixture();await f.owner.begin(destination);assert.equal(f.captures,0);assert.equal(f.opened.length,1);assert.equal(f.opened[0].destination,destination);assert.equal(f.opened[0].seed.imageId,null);assert.equal(f.opened[0].seed.lon,29);assert.match(f.opened[0].seed.description,/Overture ID: place-A/);assert.equal(f.opened[0].seed.detectionId,undefined);}});\ntest('opted-in crop and adjusted position are transferred only after an explicit map pick',async()=>{const f=fixture();await f.owner.begin('workspace',{image,pickLocation:true});assert.equal(f.opened.length,0);assert.equal(f.phases.at(-1),'picking');f.pick({lon:30,lat:42});const seed=f.opened[0].seed;assert.equal(seed.lon,30);assert.equal(seed.lat,42);assert.equal(seed.attachmentId,id);assert.equal(seed.imageId,'123');assert.match(seed.description,/2025-01-01/);assert.match(seed.description,/adjusted on map/);f.owner.cancel();assert.deepEqual(f.removed,[],'transferred image belongs to the draft');});\ntest('cancelling during a capture deletes a late saved crop and cannot open a draft',async()=>{const f=fixture();let resolve;f.setCapture(()=>new Promise(r=>resolve=r));const pending=f.owner.begin('local',{image});f.owner.cancel();resolve(id);await pending;assert.deepEqual(f.removed,[id]);assert.equal(f.opened.length,0);assert.equal(f.phases.at(-1),'idle');});\ntest('selection or destroyed-view changes cancel picking and delete its temporary image',async()=>{for(const change of[()=>({place:{...fixture().state.place,id:'other'}}),()=>({view:{destroyed:true}})]){const f=fixture();await f.owner.begin('enterprise',{image,pickLocation:true});Object.assign(f.state,change());f.owner.contextChanged();assert.equal(f.opened.length,0);assert.deepEqual(f.removed,[id]);}});\ntest('failed captures and stale image references never create a partial note',async()=>{const f=fixture();f.setCapture(async()=>{throw Error('offline')});await f.owner.begin('local',{image});assert.equal(f.opened.length,0);assert.equal(f.errors.length,1);assert.equal(f.phases.at(-1),'idle');await f.owner.begin('local',{image:{...image,imageId:'999'}});assert.equal(f.opened.length,0);assert.equal(f.captures,0);});\ntest('generic place image metadata round-trips without an invented detection and strips from display text',()=>{const seed={...image,placeId:\"place:()'A\",attachmentId:id},value=api.withPlaceAttachmentMetadata('A note',seed),parsed=api.attachmentMetadata(value);assert.equal(parsed.text,'A note');assert.equal(parsed.reference.placeId,seed.placeId);assert.equal(parsed.reference.detectionId,undefined);assert.equal(parsed.reference.attachmentId,id);assert.deepEqual(parsed.reference.bounds,image.bounds);assert(!value.includes('https://'));assert.equal(api.withPlaceAttachmentMetadata(value,seed),value);assert.equal(api.attachmentMetadata(value.replace(id,'bad')).reference,null);assert.equal(api.withPlaceAttachmentMetadata('A note',{...seed,attachmentId:'bad'}),'A note');});\ntest('place draft image association keeps manual source and title at the adjusted map position',()=>{const {FieldNoteDraft}=load('features/field-notes/FieldNoteDraft.ts');let state={imageId:'unrelated',pendingFieldNote:null,fieldNotes:[]},published=0;const owner=new FieldNoteDraft({readState:()=>state,setState:(patch,done)=>{Object.assign(state,patch);done?.()},drawRipple(){},drawPending(){},clearPending(){},persist(){},drawMapNotes(){},updateViewerNotes(){},publish(){published++;},notify(){},now:()=>1,random:()=>.1});owner.openPlace({...fixture().state.place,lon:30,lat:42},'enterprise','Source', {...image,attachmentId:id});assert.equal(state.pendingFieldNote.imageId,'123');assert.equal(state.pendingFieldNote.attachmentId,id);const note=api.withPlaceAttachmentMetadata('Source',{placeId:'place-A',...image,attachmentId:id});owner.submit('Other',note,true);assert.equal(state.fieldNotes[0].source,'manual');assert.equal(state.fieldNotes[0].lon,30);assert.equal(state.fieldNotes[0].title,'Library');assert.equal(published,1);});\ntest('Enterprise place image uses the existing real-attachment path and reconciles a lost response',async()=>{\n const source=fs.readFileSync(path.join(root,'runtime/widget.tsx'),'utf8'),sf=ts.createSourceFile('widget.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX),widget=sf.statements.find(n=>ts.isClassDeclaration(n)&&n.name?.text==='Widget'),method=widget.members.find(n=>n.name?.getText(sf)==='publishFieldNote').getText(sf),compile=s=>ts.transpileModule(s,{compilerOptions:{target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.CommonJS}}).outputText;\n let present=false,files=[],adds=0,uploads=0;class Layer{constructor(){this.geometryType='point';this.objectIdField='oid';this.fields=[{name:'gid',type:'global-id'}];this.capabilities={editing:{supportsGlobalId:true},operations:{supportsAdd:true},data:{supportsAttachment:true}}}async load(){}async queryFeatures(){return{features:present?[{attributes:{oid:1}}]:[]}}async applyEdits(){adds++;present=true;return{addFeatureResults:[{}]}}async queryAttachments(){return{1:files}}async addAttachment(feature,form){uploads++;files.push({name:form.get('attachment').name});throw Error('Lost response')}destroy(){}}\n const Runtime=new Function('attachmentMetadata','readDetectionCrop','buildEnterpriseNoteAttributes','crypto',compile('class Runtime{'+method+'};return Runtime;'))(api.attachmentMetadata,async()=> 'data:image/jpeg;base64,/9j/AAAA',()=>({}),{randomUUID:()=> '22222222-2222-4222-8222-222222222222'}),w=new Runtime(),note={id:'local',source:'manual',category:'Other',note:api.withPlaceAttachmentMetadata('Library',{...image,placeId:'place-A',attachmentId:id}),imageId:image.imageId,lon:30,lat:42};Object.assign(w,{state:{fieldNotes:[note],isGeneratingRoute:true},_sharedNoteSaves:new Set(),props:{config:{}},ArcGISModules:{FeatureLayer:Layer,Graphic:class{constructor(p){Object.assign(this,p)}}},sharedNotesUrl:()=> 'https://enterprise.test/FeatureServer/0',patchSharedFieldNote:async(id,patch)=>{Object.assign(note,patch);return true},showToast(){},_t:text=>text});await w.publishFieldNote('local');assert.equal(note.sharedStatus,'failed');await w.publishFieldNote('local');assert.equal(note.sharedStatus,'shared');assert.equal(adds,1);assert.equal(uploads,1);assert.equal(note.source,'manual');\n});\n"
